{
  "name": "ocaml",
  "version": "5.5.1000",
  "description": "OCaml compiler packaged for esy",
  "esy": {
    "buildsInSource": true,
    "build": [
      "#{os == 'windows' ? 'sh ./setup-flexdll': 'true'}",
      "./configure --prefix #{self.install} #{os == 'windows' ? '--host=x86_64-w64-mingw32 --with-flexdll=flexdll': ''}",
      "make -j#{self.jobs}"
    ],
    "install": "make install",
    "buildEnv": {},
    "exportedEnv": {
      "OCAMLPATH": {
        "val": "#{ocaml.lib / 'ocaml' : $OCAMLPATH}",
        "scope": "global"
      },
      "OCAMLLIB": {
        "val": "#{ocaml.lib / 'ocaml'}",
        "scope": "global"
      },
      "CAML_LD_LIBRARY_PATH": {
        "val": "#{ocaml.lib / 'ocaml' / 'stublibs' : ocaml.lib / 'ocaml' : $CAML_LD_LIBRARY_PATH}",
        "scope": "global"
      },
      "OCAML_TOPLEVEL_PATH": {
        "val": "#{ocaml.lib / 'ocaml'}",
        "scope": "global"
      }
    }
  },
  "dependencies": {}
}
